// Strip markdown code fences that free models add despite instructions
const raw = $input.first().json.output;

let cleaned = raw;
if (typeof cleaned === 'string') {
  // Remove ```json ... ``` or ``` ... ``` wrappers
  cleaned = cleaned.replace(/^```json\s*/i, '').replace(/^```\s*/i, '');
  cleaned = cleaned.replace(/\s*```\s*$/i, '').trim();
}

// Try to parse and re-stringify to validate JSON
try {
  const parsed = JSON.parse(cleaned);
  return [{ json: { output: JSON.stringify(parsed) } }];
} catch (e) {
  // If still broken, extract JSON object between first { and last }
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      const parsed = JSON.parse(match[0]);
      return [{ json: { output: JSON.stringify(parsed) } }];
    } catch (e2) {
      throw new Error('JSON extraction failed: ' + cleaned.substring(0, 200));
    }
  }
  throw new Error('No JSON object found in output: ' + cleaned.substring(0, 200));
}
